window.EL_CAPSULES = window.EL_CAPSULES || {};
Object.assign(window.EL_CAPSULES, {
  "p3:Oct:1": {"title": "Un reino nuevo en Hispania", "steps": [{"type": "hook", "kicker": "Historia viva", "h": "¿Quién gobernaba España hace 1500 años?", "scenario": "Imagina que vives en el año 600 y tu rey no es español ni romano, sino godo. Ha llegado desde el norte de Europa y ahora manda en casi toda Hispania.", "body": "Los <b>visigodos</b> fueron un pueblo germánico que llegó a la Península Ibérica tras la caída del Imperio Romano. Crearon un <b>reino</b> propio con capital en Toledo y gobernaron gran parte de España durante casi 300 años."}, {"type": "theory", "kicker": "Lo esencial", "h": "El reino visigodo: territorio y organización", "body": "Los visigodos organizaron su reino con un <b>rey</b> a la cabeza, ayudado por <b>duques y condes</b> que gobernaban cada territorio. Su capital, <b>Toledo</b>, se convirtió en el centro político y religioso de Hispania. Convivieron con la población hispanorromana, de la que aprendieron costumbres, leyes y lengua.", "diagram": "REINO VISIGODO<br><b>Capital:</b> Toledo<br><b>Rey</b> → <b>Duques</b> → <b>Condes</b><br><b>Territorio:</b> casi toda Hispania"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Dónde estaba la capital del reino visigodo?", "q": "¿Cuál era la capital del reino visigodo en Hispania?", "opts": [{"t": "Toledo", "ok": true}, {"t": "Barcelona", "ok": false}, {"t": "Sevilla", "ok": false}], "okMsg": "¡Correcto! Toledo fue la capital y el centro del poder visigodo.", "noMsg": "No es esa. La capital visigoda fue Toledo, en el centro de la península."}, {"type": "reflect", "kicker": "Tu turno", "h": "Datos clave de los visigodos", "body": "En tu cuaderno, escribe todo lo que has aprendido hoy sobre los visigodos: quiénes eran, dónde vivían y cómo se organizaban.", "prompt": "Escribe 5 datos clave sobre los visigodos que hayas aprendido en esta cápsula. Puedes subrayarlos en tu cuaderno con un color llamativo."}]},
  "p3:Oct:2": {"title": "Un rey cambia de fe", "steps": [{"type": "hook", "kicker": "Un momento decisivo", "h": "¿Puede la decisión de un rey cambiar la historia de todo un país?", "scenario": "En el año 589, el rey Recaredo reunió a los obispos más importantes del reino en Toledo. Lo que allí anunció cambiaría la religión de España para siempre.", "body": "Recaredo era el rey de los visigodos, y hasta entonces su pueblo practicaba una forma de cristianismo llamada <b>arrianismo</b>, distinta a la de la mayoría de la población hispanorromana, que era <b>católica</b>."}, {"type": "theory", "kicker": "Lo esencial", "h": "La conversión de Recaredo al catolicismo (589)", "body": "En el <b>III Concilio de Toledo</b>, el rey <b>Recaredo</b> anunció públicamente su conversión al <b>catolicismo</b>, la misma fe que profesaba la mayoría de sus súbditos hispanorromanos. Con esta decisión, godos e hispanorromanos compartieron por primera vez la misma religión, lo que ayudó a <b>unir</b> a los dos pueblos en un solo reino.", "diagram": "AÑO 589<br>Rey <b>Recaredo</b><br>Arrianismo → <b>Catolicismo</b><br>Resultado: <b>unión religiosa</b> de godos e hispanorromanos"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿En qué año se convirtió Recaredo al catolicismo?", "q": "¿En qué año Recaredo anunció su conversión al catolicismo?", "opts": [{"t": "589", "ok": true}, {"t": "711", "ok": false}, {"t": "1492", "ok": false}], "okMsg": "¡Exacto! En el año 589, en el III Concilio de Toledo.", "noMsg": "No es ese año. Recaredo se convirtió al catolicismo en el 589."}, {"type": "reflect", "kicker": "Investiga", "h": "¿Por qué fue tan importante esta conversión?", "body": "La conversión de Recaredo no fue solo algo religioso: ayudó a unir a dos pueblos que vivían juntos pero con creencias distintas.", "prompt": "Investiga y escribe con tus palabras: ¿por qué crees que fue importante para España que el rey Recaredo se convirtiera al catolicismo? Da al menos una razón."}]},
  "p3:Oct:3": {"title": "Piedras que cuentan la fe", "steps": [{"type": "hook", "kicker": "Un tesoro escondido", "h": "¿Puede una iglesia tener 1400 años y seguir en pie?", "scenario": "En un pueblo de Palencia hay una iglesia tan antigua que fue construida por los propios visigodos. Sus piedras han visto pasar reyes, guerras y muchos siglos de historia.", "body": "Los visigodos, ya convertidos al catolicismo, construyeron <b>iglesias</b> que todavía hoy podemos visitar en España. Son algunos de los edificios cristianos más antiguos de toda Europa."}, {"type": "theory", "kicker": "Lo esencial", "h": "Iglesias visigodas: San Juan de Baños y San Pedro de la Nave", "body": "<b>San Juan de Baños</b> (Palencia) es una de las iglesias más antiguas de España, construida en el siglo VII. <b>San Pedro de la Nave</b> (Zamora) es otro ejemplo impresionante de arquitectura visigoda. Ambas tienen el característico <b>arco de herradura</b>, una forma que después se repetiría en muchos edificios españoles.", "diagram": "IGLESIAS VISIGODAS<br><b>San Juan de Baños</b> — Palencia<br><b>San Pedro de la Nave</b> — Zamora<br>Elemento típico: <b>arco de herradura</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué forma es típica de la arquitectura visigoda?", "q": "¿Qué elemento arquitectónico es característico de las iglesias visigodas?", "opts": [{"t": "El arco de herradura", "ok": true}, {"t": "Las torres de cristal", "ok": false}, {"t": "Los tejados de paja", "ok": false}], "okMsg": "¡Correcto! El arco de herradura es la seña de identidad de estas iglesias.", "noMsg": "No es esa. El arco de herradura es el elemento típico visigodo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Dibuja una iglesia visigoda", "body": "Busca información sobre una iglesia visigoda de España, como San Juan de Baños o San Pedro de la Nave.", "prompt": "Dibuja una iglesia visigoda en tu cuaderno. Escribe debajo su nombre y en qué localidad de España se encuentra."}]},
  "p3:Oct:4": {"title": "La verdad que nos hace libres", "steps": [{"type": "hook", "kicker": "Una promesa muy antigua", "h": "¿Qué tiene que ver la fe de un rey visigodo con la Biblia?", "scenario": "Recaredo eligió la fe católica porque creía que era la verdad. Muchos siglos antes, Jesús ya había hablado de lo poderosa que es la verdad.", "body": "Este mes hemos visto cómo la <b>fe cristiana</b> marcó la historia de los visigodos. Hoy vamos a leer las palabras de Jesús sobre la verdad, el mismo valor que llevó a un rey a cambiar de religión."}, {"type": "theory", "kicker": "Lo esencial", "h": "Juan 8:32: la verdad os hará libres", "body": "Jesús dijo: 'Y conoceréis la verdad, y la verdad os hará libres' (Juan 8:32). Conocer la verdad de Dios no nos encierra, sino que nos da <b>libertad</b> de verdad: libertad para vivir de forma correcta y en paz. Para Recaredo, aceptar esa verdad significó unir a su pueblo bajo una misma fe.", "diagram": "JUAN 8:32<br>'Conoceréis la <b>verdad</b>...<br>...y la verdad os hará <b>libres</b>'<br>La fe de Recaredo → unión y libertad para su pueblo"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué nos regala la verdad, según Jesús?", "q": "Según Juan 8:32, ¿qué produce en nosotros conocer la verdad?", "opts": [{"t": "Libertad", "ok": true}, {"t": "Riqueza", "ok": false}, {"t": "Miedo", "ok": false}], "okMsg": "¡Correcto! Jesús dijo que la verdad nos hace libres.", "noMsg": "No es esa. Juan 8:32 dice que la verdad nos hace libres."}, {"type": "reflect", "kicker": "Proyecto final", "h": "Los visigodos en España", "body": "Ya conoces el territorio visigodo, la conversión de Recaredo, sus iglesias y el valor de la verdad según la Biblia. Es momento de reunirlo todo.", "prompt": "Elabora tu trabajo 'Los visigodos en España': explica qué significó la fe cristiana para los visigodos, usando lo que has aprendido este mes sobre Recaredo, las iglesias visigodas y el versículo de Juan 8:32."}]},
  "p3:Nov:1": {"title": "Un mapa de mil colores", "steps": [{"type": "hook", "kicker": "Geografía sorprendente", "h": "¿Por qué en España hace tanto sol en el sur y tanta lluvia en el norte?", "scenario": "Imagina que un amigo de Galicia te dice que hoy llueve y hace fresco, mientras que tú, desde Almería, le respondes que hace calor y no ha llovido en semanas. ¡Y estáis en el mismo país!", "body": "España no tiene un solo clima, sino <b>varios climas distintos</b> según la zona. Conocerlos nos ayuda a entender por qué el paisaje, la ropa e incluso los cultivos cambian tanto de un lugar a otro."}, {"type": "theory", "kicker": "Lo esencial", "h": "Los 5 climas de España", "body": "En España conviven cinco climas: el <b>mediterráneo</b> (veranos calurosos y secos, en la costa este y sur), el <b>oceánico</b> (lluvias frecuentes todo el año, en el norte), el <b>continental</b> (inviernos fríos y veranos muy calurosos, en el interior), el <b>árido</b> (muy poca lluvia, en el sureste) y el <b>canario</b> (temperaturas suaves todo el año, en las Islas Canarias).", "diagram": "CLIMAS DE ESPAÑA<br><b>Mediterráneo</b> — este y sur<br><b>Oceánico</b> — norte<br><b>Continental</b> — interior<br><b>Árido</b> — sureste<br><b>Canario</b> — islas Canarias"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué clima predomina en el norte de España?", "q": "¿Qué clima tiene lluvias frecuentes durante todo el año y se da en el norte de España?", "opts": [{"t": "El clima oceánico", "ok": true}, {"t": "El clima árido", "ok": false}, {"t": "El clima canario", "ok": false}], "okMsg": "¡Correcto! El clima oceánico trae lluvias durante todo el año en el norte.", "noMsg": "No es ese. El clima del norte, con lluvias constantes, es el oceánico."}, {"type": "reflect", "kicker": "Tu turno", "h": "Colorea el mapa climático", "body": "Con lo que has aprendido sobre los 5 climas de España, ya puedes representar cada zona en un mapa.", "prompt": "Dibuja o imprime un mapa de España. Colorea cada zona climática con un color distinto (mediterráneo, oceánico, continental, árido y canario) y escribe el nombre de cada clima junto a su color."}]},
  "p3:Nov:2": {"title": "El clima de mi rincón del mundo", "steps": [{"type": "hook", "kicker": "Investigador por un día", "h": "¿Sabrías explicar el clima del lugar donde vives?", "scenario": "Un amigo de otro país te pregunta: '¿Cómo es el clima donde vives, hace mucho calor o mucho frío?' Te das cuenta de que nunca lo has investigado de verdad.", "body": "No es lo mismo el <b>tiempo</b> de hoy (si llueve o hace sol ahora mismo) que el <b>clima</b> de un lugar, que son las condiciones que se repiten durante todo el año."}, {"type": "theory", "kicker": "Lo esencial", "h": "Cómo se describe un clima", "body": "Para describir el clima de un lugar usamos datos como el <b>tipo de clima</b> (mediterráneo, oceánico...), la <b>temperatura media</b> (el promedio de calor o frío durante el año) y la <b>precipitación anual</b> (cuánta lluvia cae en total en un año). Estos datos nos permiten comparar el clima de distintas ciudades.", "diagram": "DATOS DE UN CLIMA<br><b>Tipo de clima</b><br><b>Temperatura media</b><br><b>Precipitación anual</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Tiempo o clima?", "q": "Si hoy llueve en tu ciudad, pero normalmente no suele llover, ¿de qué estamos hablando?", "opts": [{"t": "Del tiempo de hoy", "ok": true}, {"t": "Del clima de la ciudad", "ok": false}, {"t": "De la precipitación anual", "ok": false}], "okMsg": "¡Correcto! Lo que pasa en un día concreto es el tiempo, no el clima.", "noMsg": "No es eso. Lo que ocurre en un solo día es el tiempo, no el clima general."}, {"type": "reflect", "kicker": "Investiga", "h": "El clima de mi ciudad", "body": "Busca información sobre el clima de la ciudad donde vives, preguntando a un adulto o consultando fuentes fiables.", "prompt": "Investiga y anota: el tipo de clima de tu ciudad, su temperatura media aproximada y su precipitación anual aproximada."}]},
  "p3:Nov:3": {"title": "Paisajes que cambian con el clima", "steps": [{"type": "hook", "kicker": "Un viaje sin moverse", "h": "¿Por qué en el norte hay tanto verde y en el sur tanto campo seco?", "scenario": "Si viajas desde las montañas verdes de Asturias hasta los campos secos de Murcia, sientes que has cambiado de país, aunque sigues en España.", "body": "El <b>clima</b> de cada zona influye directamente en su <b>paisaje</b> y en cómo viven las personas: qué cultivan, qué animales crían y hasta cómo son sus casas."}, {"type": "theory", "kicker": "Lo esencial", "h": "Paisajes naturales y forma de vida", "body": "España tiene paisajes muy variados: <b>montañas</b>, <b>mesetas</b>, <b>costas</b> y <b>zonas áridas</b>. Donde llueve mucho, como en el norte, crecen bosques verdes y hay ganadería. Donde el clima es seco, como en el sureste, predominan los <b>olivares</b> y los cultivos que necesitan poca agua.", "diagram": "CLIMA → PAISAJE → FORMA DE VIDA<br>Oceánico → bosques verdes → ganadería<br>Árido → tierras secas → olivares y regadío"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué cultivo es típico de zonas con clima seco?", "q": "¿Qué cultivo es muy habitual en las zonas de clima mediterráneo y árido de España?", "opts": [{"t": "El olivo", "ok": true}, {"t": "El plátano de Canarias", "ok": false}, {"t": "El bosque de robles", "ok": false}], "okMsg": "¡Correcto! El olivo resiste bien la sequía y abunda en el sur y el este.", "noMsg": "No es ese. El cultivo típico de zonas secas mediterráneas es el olivo."}, {"type": "reflect", "kicker": "Compara", "h": "Mi paisaje y otro paisaje de España", "body": "Piensa en el paisaje de tu comunidad autónoma y compáralo con el de otra región de España que tenga un clima distinto.", "prompt": "Escribe 2 diferencias entre el paisaje de tu región y el de otra comunidad autónoma española. Puedes fijarte en la vegetación, el terreno o los cultivos."}]},
  "p3:Nov:4": {"title": "Las estaciones no cesarán", "steps": [{"type": "hook", "kicker": "Una promesa para siempre", "h": "¿Quién asegura que después del invierno siempre llega la primavera?", "scenario": "Cada año, sin falta, después del frío del invierno llega el calor de la primavera y el verano. Nunca falla, año tras año.", "body": "Este mes hemos estudiado los climas y paisajes de España, y hemos visto que las <b>estaciones</b> se repiten siempre siguiendo un orden. La Biblia también habla de esta promesa de Dios."}, {"type": "theory", "kicker": "Lo esencial", "h": "Génesis 8:22: las estaciones no cesarán", "body": "Después del diluvio, Dios prometió: 'Mientras la tierra permanezca, la siembra y la siega no cesarán' (Génesis 8:22). Es la promesa de que el <b>orden de la naturaleza</b> —el frío y el calor, la siembra y la cosecha, las estaciones— seguirá funcionando siempre, gracias a la fidelidad de Dios.", "diagram": "GÉNESIS 8:22<br>Siembra y siega<br>Frío y calor<br>Verano e invierno<br>→ NO CESARÁN, por promesa de Dios"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué promete Dios en Génesis 8:22?", "q": "Según Génesis 8:22, ¿qué promete Dios que no cesará mientras la tierra permanezca?", "opts": [{"t": "La siembra y la siega (las estaciones)", "ok": true}, {"t": "Las guerras entre países", "ok": false}, {"t": "El precio de los alimentos", "ok": false}], "okMsg": "¡Correcto! Dios prometió que las estaciones y los ciclos de la naturaleza no cesarán.", "noMsg": "No es esa. Génesis 8:22 promete que la siembra, la siega y las estaciones no cesarán."}, {"type": "reflect", "kicker": "Proyecto final", "h": "Mapa climático + ficha de mi ciudad", "body": "Has estudiado los climas de España, investigado el clima de tu ciudad y comparado paisajes. Ahora es el momento de reunir todo tu trabajo.", "prompt": "Prepara tu entregable final: el mapa climático de España coloreado y una ficha con el clima de tu ciudad (tipo, temperatura media y precipitación anual). Añade una frase sobre cómo las estaciones se repiten cada año, tal como promete Génesis 8:22."}]},
  "p3:Dic:1": {"title": "El texto que enseña: la romanización", "steps": [{"type": "hook", "kicker": "Detective de textos", "h": "¿Sabías que los textos también tienen esqueleto?", "scenario": "Imagina que abres un libro de historia y lees sobre los romanos en Hispania.", "body": "Todos los textos que <b>explican algo</b> tienen una estructura secreta con tres partes. Hoy vas a descubrirla leyendo un texto sobre la romanización."}, {"type": "theory", "kicker": "Aprende", "h": "Las tres partes del texto expositivo", "body": "Un texto expositivo explica un tema con datos reales, sin opiniones. Siempre tiene <b>introducción</b> (presenta el tema), <b>desarrollo</b> (explica con detalles) y <b>conclusión</b> (resume la idea principal).", "diagram": "<b>INTRODUCCIÓN</b><br>¿De qué trata?<br><b>DESARROLLO</b><br>Datos y explicaciones<br><b>CONCLUSIÓN</b><br>Resumen final"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué parte va primero?", "q": "¿Qué parte de un texto expositivo presenta el tema al principio?", "opts": [{"t": "La introducción", "ok": true}, {"t": "El desarrollo", "ok": false}, {"t": "La conclusión", "ok": false}], "okMsg": "Exacto. La introducción abre el texto y presenta el tema.", "noMsg": "Casi. La que presenta el tema al principio es la introducción."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Analiza un texto real", "body": "Lee con atención un texto expositivo sobre la romanización de Hispania y localiza sus tres partes.", "prompt": "Lee con un adulto un texto sobre la romanización de Hispania. Después, escribe con tus palabras: ¿cuál es la introducción, cuál el desarrollo y cuál la conclusión?"}]},
  "p3:Dic:2": {"title": "Mi comunidad autónoma en palabras", "steps": [{"type": "hook", "kicker": "Escritor en acción", "h": "¿Podrías explicar tu tierra a alguien que nunca la ha visitado?", "scenario": "Un amigo de otro país te pregunta cómo es tu comunidad autónoma.", "body": "Vas a convertirte en un pequeño <b>escritor experto</b> y crear tu propio texto expositivo sobre el lugar donde vives."}, {"type": "theory", "kicker": "Aprende", "h": "Cómo escribir un buen texto expositivo", "body": "Para escribir bien, usa <b>vocabulario específico</b> de geografía e historia (relieve, clima, monumentos, tradiciones) y organiza tus ideas en introducción, desarrollo y conclusión.", "diagram": "<b>INTRODUCCIÓN</b><br>Nombra tu comunidad<br><b>DESARROLLO</b><br>3-4 datos: geografía, clima, costumbres<br><b>CONCLUSIÓN</b><br>Por qué te gusta"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Vocabulario preciso", "q": "¿Cuál de estas palabras es vocabulario específico de geografía?", "opts": [{"t": "Relieve", "ok": true}, {"t": "Bonito", "ok": false}, {"t": "Contento", "ok": false}], "okMsg": "Correcto. 'Relieve' es un término preciso de geografía.", "noMsg": "No es esa. 'Relieve' es la palabra específica de geografía."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu texto expositivo", "body": "Ahora te toca escribir tu propio texto expositivo sobre tu comunidad autónoma.", "prompt": "Escribe 10 oraciones sobre tu comunidad autónoma: incluye introducción, desarrollo (con datos de geografía e historia) y conclusión."}]},
  "p3:Dic:3": {"title": "Mayúsculas que dan nombre a España", "steps": [{"type": "hook", "kicker": "Detective de textos", "h": "¿Por qué España, Madrid y el Ebro llevan mayúscula?", "scenario": "Ves un mapa lleno de nombres: ríos, ciudades y comunidades.", "body": "Hoy descubrirás la regla de las <b>mayúsculas en los nombres propios</b> y topónimos, esos nombres que señalan lugares únicos."}, {"type": "theory", "kicker": "Aprende", "h": "La regla de los nombres propios", "body": "Los <b>topónimos</b> (nombres de lugares) y los nombres propios de personas siempre se escriben con mayúscula inicial: Madrid, Ebro, Andalucía. Las palabras comunes como río, ciudad o comunidad se escriben en minúscula, salvo que empiecen la oración.", "diagram": "<b>MAYÚSCULA</b><br>Nombres propios: Duero, Sevilla, Aragón<br><b>MINÚSCULA</b><br>Palabras comunes: río, ciudad, comunidad"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Mayúscula o minúscula?", "q": "¿Cuál de estas palabras se escribe siempre con mayúscula?", "opts": [{"t": "Cantabria", "ok": true}, {"t": "montaña", "ok": false}, {"t": "ciudad", "ok": false}], "okMsg": "Bien. Cantabria es un nombre propio, por eso lleva mayúscula.", "noMsg": "No es esa. Cantabria es el nombre propio y por eso lleva mayúscula."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Tu lista de nombres propios", "body": "Vas a practicar las mayúsculas escribiendo nombres reales de España.", "prompt": "Haz una lista de 15 nombres propios de España: ríos, ciudades y comunidades autónomas. Recuerda escribir la primera letra en mayúscula."}]},
  "p3:Dic:4": {"title": "La palabra dicha como conviene", "steps": [{"type": "hook", "kicker": "Un tesoro de palabras", "h": "¿Puede una palabra ser como una joya?", "scenario": "A veces decimos algo en el momento exacto y ayuda mucho; otras veces hablamos sin pensar y hacemos daño.", "body": "La Biblia compara las <b>palabras bien dichas</b> con algo muy valioso: manzanas de oro. Hoy aprenderás por qué."}, {"type": "theory", "kicker": "Aprende", "h": "Proverbios 25:11: un tesoro de palabras", "body": "El versículo dice: <i>«Como manzanas de oro con figuras de plata es la palabra dicha como conviene»</i> (Proverbios 25:11). Esto significa que hablar con <b>precisión, en el momento adecuado</b> y con cariño es tan valioso como una joya. Igual que aprendiste a organizar bien un texto expositivo, Dios nos enseña a organizar bien nuestras palabras.", "diagram": "PALABRA DICHA A TIEMPO<br>= <b>manzanas de oro</b><br>con <b>figuras de plata</b><br>(Proverbios 25:11)"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Un versículo precioso", "q": "Según Proverbios 25:11, ¿con qué se compara una palabra dicha en el momento adecuado?", "opts": [{"t": "Con manzanas de oro", "ok": true}, {"t": "Con una piedra", "ok": false}, {"t": "Con el viento", "ok": false}], "okMsg": "Así es. El versículo la compara con manzanas de oro y figuras de plata.", "noMsg": "No es esa. El versículo habla de manzanas de oro con figuras de plata."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Una palabra en su momento", "body": "Piensa en un momento en que una palabra amable ayudó a alguien.", "prompt": "Escribe o dibuja una situación en la que dijiste (o alguien te dijo) una palabra buena en el momento justo. Añade una frase final explicando qué aprendiste de Proverbios 25:11."}]},
  "p3:Feb:1": {"title": "El mapa de los reinos cristianos", "steps": [{"type": "hook", "kicker": "Viaje al pasado", "h": "¿Sabías que España no siempre fue un solo reino?", "scenario": "Imagina un mapa de hace 900 años, dividido en varios reinos que luchaban y convivían.", "body": "En el siglo XII, la península estaba repartida entre distintos <b>reinos cristianos</b> del norte y territorios musulmanes del sur. Hoy vas a conocer esos reinos."}, {"type": "theory", "kicker": "Aprende", "h": "Los reinos cristianos del norte", "body": "Durante la Edad Media, en el norte de la península existían varios reinos cristianos: <b>Castilla</b>, <b>Aragón</b> y <b>Navarra</b>. Cada uno tenía su propio rey, sus leyes y su territorio, aunque a veces se unían para luchar juntos.", "diagram": "REINOS CRISTIANOS (siglo XII)<br><b>Castilla</b> · <b>Aragón</b> · <b>Navarra</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Reinos del norte", "q": "¿Cuál de estos era uno de los reinos cristianos del norte en el siglo XII?", "opts": [{"t": "Aragón", "ok": true}, {"t": "Egipto", "ok": false}, {"t": "Persia", "ok": false}], "okMsg": "Correcto. Aragón era uno de los reinos cristianos del norte.", "noMsg": "No es ese. Aragón sí era uno de los reinos cristianos del norte."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Dibuja el mapa medieval", "body": "Vas a dibujar tu propio mapa de los reinos medievales.", "prompt": "Dibuja un mapa sencillo de la península en el siglo XII. Colorea de un color distinto Castilla, Aragón y Navarra, y escribe el nombre de cada uno junto a su territorio."}]},
  "p3:Feb:2": {"title": "El Camino de Santiago", "steps": [{"type": "hook", "kicker": "Viaje al pasado", "h": "¿Un camino que cruza toda Europa a pie?", "scenario": "Durante siglos, miles de personas caminaron cientos de kilómetros hasta un mismo lugar.", "body": "Ese camino existe todavía hoy: el <b>Camino de Santiago</b>. Esta semana vas a trazar una de sus rutas más famosas."}, {"type": "theory", "kicker": "Aprende", "h": "La Ruta Francesa", "body": "El Camino de Santiago es una ruta de peregrinación que lleva hasta la <b>tumba del apóstol Santiago</b>, en Santiago de Compostela. La <b>Ruta Francesa</b> es la más conocida: entra por los Pirineos y atraviesa ciudades como Pamplona, Burgos y León antes de llegar a Compostela.", "diagram": "RUTA FRANCESA<br>Pirineos → Pamplona → Burgos → León → <b>Santiago de Compostela</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Destino final", "q": "¿A qué ciudad llega finalmente la Ruta Francesa del Camino de Santiago?", "opts": [{"t": "Santiago de Compostela", "ok": true}, {"t": "Barcelona", "ok": false}, {"t": "Sevilla", "ok": false}], "okMsg": "Exacto. La Ruta Francesa termina en Santiago de Compostela.", "noMsg": "No es esa. La Ruta Francesa termina en Santiago de Compostela."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Traza tu ruta", "body": "Traza la Ruta Francesa en un mapa y anota las ciudades por las que pasa.", "prompt": "Dibuja o calca un mapa de España y traza con una línea la Ruta Francesa del Camino de Santiago. Anota al menos tres ciudades principales por las que pasa."}]},
  "p3:Feb:3": {"title": "Un peregrino medieval", "steps": [{"type": "hook", "kicker": "Viaje al pasado", "h": "¿Te imaginas caminar semanas enteras sin coche ni mapa con GPS?", "scenario": "Un campesino medieval decide dejar su casa y caminar cientos de kilómetros hasta Santiago.", "body": "Detrás de cada peregrino había una <b>historia y un motivo</b>. Esta semana investigarás cómo era realmente ese viaje."}, {"type": "theory", "kicker": "Aprende", "h": "La vida de un peregrino medieval", "body": "Los peregrinos medievales viajaban por distintos <b>motivos</b>: cumplir una promesa, pedir perdón por sus pecados o buscar sanación. El viaje podía durar <b>semanas o meses</b> y estaba lleno de <b>peligros</b>: bandidos, enfermedades, hambre y mal tiempo. Por eso, a lo largo del camino se construyeron hospitales y albergues para ayudarlos.", "diagram": "PEREGRINO MEDIEVAL<br><b>Motivación:</b> fe, promesa, perdón<br><b>Duración:</b> semanas o meses<br><b>Peligros:</b> bandidos, enfermedades, cansancio"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Peligros del camino", "q": "¿Cuál era un peligro real para los peregrinos medievales en el Camino?", "opts": [{"t": "Los bandidos", "ok": true}, {"t": "Los aviones", "ok": false}, {"t": "Los coches", "ok": false}], "okMsg": "Correcto. Los bandidos eran uno de los grandes peligros del camino.", "noMsg": "No es ese. En la Edad Media el peligro real eran los bandidos, no los aviones ni los coches."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Investiga a un peregrino", "body": "Investiga cómo era la vida de un peregrino medieval.", "prompt": "Investiga y escribe tres datos sobre un peregrino medieval: por qué viajaba, cuánto tiempo tardaba y qué peligros encontraba en el camino."}]},
  "p3:Feb:4": {"title": "La Iglesia que nunca cae", "steps": [{"type": "hook", "kicker": "Un edificio distinto", "h": "¿Qué construcción puede resistir más de 2000 años?", "scenario": "Los peregrinos medievales construían catedrales enormes que todavía siguen en pie.", "body": "Pero hay una construcción todavía más fuerte que cualquier catedral de piedra: la que Jesús prometió edificar. Esta semana descubrirás cuál es."}, {"type": "theory", "kicker": "Aprende", "h": "Mateo 16:18: la promesa de Jesús", "body": "Jesús dijo: <i>«Edificaré mi iglesia y las puertas del Hades no prevalecerán»</i> (Mateo 16:18). Aquí <b>iglesia</b> no significa solo un edificio de piedra, como las catedrales del Camino de Santiago, sino la comunidad de personas que creen en Jesús. Él promete que nada podrá destruirla.", "diagram": "MATEO 16:18<br>«Edificaré <b>mi iglesia</b>»<br>Las puertas del Hades <b>no prevalecerán</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "La promesa de Jesús", "q": "Según Mateo 16:18, ¿qué prometió Jesús construir?", "opts": [{"t": "Su iglesia", "ok": true}, {"t": "Un castillo", "ok": false}, {"t": "Un puente", "ok": false}], "okMsg": "Así es. Jesús prometió edificar su iglesia.", "noMsg": "No es eso. Jesús prometió edificar su iglesia, no un castillo ni un puente."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Dos construcciones, una promesa", "body": "Relaciona la promesa de Jesús con las catedrales medievales que conociste.", "prompt": "Escribe o dibuja: ¿en qué se parece y en qué se diferencia una catedral de piedra del Camino de Santiago con «la iglesia» que Jesús prometió edificar según Mateo 16:18?"}]},
  "p3:Mar:1": {"title": "El secreto de las leyendas", "steps": [{"type": "hook", "kicker": "Leyendas españolas", "h": "¿Sabías que las leyendas guardan un secreto al final?", "scenario": "Tu abuela te cuenta una historia antigua de un caballero, un dragón o un pueblo encantado. Al terminar, te dice: <b>«Y de esto se aprendió algo importante»</b>.", "body": "Las <b>leyendas</b> son relatos que se han contado de generación en generación en España. Mezclan hechos reales con imaginación, y casi siempre terminan enseñando una lección de vida: la <b>moraleja</b>."}, {"type": "theory", "kicker": "Cómo se construye una leyenda", "h": "Las tres partes de toda leyenda", "body": "Toda leyenda española sigue una <b>estructura</b> parecida: primero se presenta un lugar y un personaje; después ocurre un hecho misterioso o extraordinario; y al final queda una <b>moraleja</b>, es decir, la enseñanza que la historia nos deja.", "diagram": "<b>Presentación</b>: lugar y personaje<br><b>Nudo</b>: hecho misterioso<br><b>Moraleja</b>: la lección final"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué es la moraleja de una leyenda?", "q": "¿Cuál de estas frases explica mejor qué es la <b>moraleja</b>?", "opts": [{"t": "La lección o enseñanza que deja la historia", "ok": true}, {"t": "El nombre del pueblo donde ocurre la leyenda", "ok": false}, {"t": "La fecha exacta en la que sucedió el relato", "ok": false}], "okMsg": "¡Exacto! La moraleja es el mensaje que la leyenda quiere transmitirte.", "noMsg": "Casi. La moraleja es la enseñanza o lección que nos deja la historia, no un dato ni una fecha."}, {"type": "reflect", "kicker": "Tu turno", "h": "Empieza tu cuaderno de leyendas", "body": "Busca (con ayuda de un adulto, un libro o internet) una leyenda española conocida, como la del Cid, la Cava Rumía o el Lago de Sanabria. Léela con atención antes de continuar.", "prompt": "Escribe un resumen de la leyenda en <b>exactamente 6 oraciones</b> y, al final, añade una frase que diga cuál crees que es su <b>moraleja</b>."}]},
  "p3:Mar:2": {"title": "Palabras con magia", "steps": [{"type": "hook", "kicker": "El lenguaje de las leyendas", "h": "¿Puede una montaña «vigilar» un pueblo?", "scenario": "En muchas leyendas leemos frases como <b>«el río lloraba»</b> o <b>«sus ojos eran como dos brasas»</b>. Un río no llora de verdad, pero la imagen nos ayuda a imaginar mejor la historia.", "body": "Los escritores usan <b>recursos literarios</b> para hacer las leyendas más bonitas e impactantes. Hoy descubrirás dos de los más usados: la <b>personificación</b> y la <b>comparación</b>."}, {"type": "theory", "kicker": "Dos recursos muy usados", "h": "Personificación y comparación", "body": "La <b>personificación</b> da cualidades humanas a algo que no es humano (por ejemplo: «el viento susurraba»). La <b>comparación</b> relaciona dos cosas distintas usando palabras como «como» o «parecía» (por ejemplo: «fuerte como un roble»). Además, muchas leyendas incluyen una <b>referencia histórica</b>: un rey, una batalla o un lugar que existió de verdad.", "diagram": "<b>Personificación</b>: cosas que actúan como personas<br><b>Comparación</b>: «X es como Y»<br><b>Referencia histórica</b>: dato real dentro del relato"}, {"type": "quiz", "kicker": "Identifica el recurso", "h": "¿Qué recurso literario es este?", "q": "En la frase <b>«la montaña observaba en silencio a los viajeros»</b>, ¿qué recurso literario se usa?", "opts": [{"t": "Personificación", "ok": true}, {"t": "Una referencia histórica", "ok": false}, {"t": "Una fecha exacta", "ok": false}], "okMsg": "¡Correcto! La montaña «observa», una acción propia de personas: eso es personificación.", "noMsg": "No del todo. Dar a la montaña la capacidad de «observar» es darle una cualidad humana: eso se llama personificación."}, {"type": "reflect", "kicker": "Investiga tu leyenda", "h": "Caza recursos en tu leyenda", "body": "Vuelve a la leyenda que leíste la semana pasada (o elige otra) y busca dentro de ella un recurso literario y un dato histórico real.", "prompt": "Escribe en tu cuaderno: 1) una frase de la leyenda que sea <b>personificación o comparación</b>, y 2) una <b>referencia histórica</b> (persona, lugar o época real) que aparezca en el relato."}]},
  "p3:Mar:3": {"title": "Leyendas de mi tierra", "steps": [{"type": "hook", "kicker": "Cerca de casa", "h": "¿Hay una leyenda escondida en tu propio pueblo?", "scenario": "Casi todos los pueblos y ciudades de España tienen una historia antigua que se cuenta desde hace generaciones: sobre un puente, una fuente, un castillo o un personaje misterioso.", "body": "Esta semana serás un <b>investigador de leyendas locales</b>. Vas a descubrir una historia propia de tu región, esa que quizá tus abuelos o vecinos conocen."}, {"type": "theory", "kicker": "Cómo investigar una leyenda local", "h": "Fuentes para encontrar tu leyenda", "body": "Para encontrar una leyenda de tu ciudad o provincia puedes preguntar a <b>familiares mayores</b>, visitar la <b>biblioteca</b> de tu localidad, o buscar información en la web del <b>ayuntamiento</b>. Muchas leyendas explican por qué existe una calle, una piedra o una fiesta local.", "diagram": "<b>Preguntar</b>: familia y vecinos<br><b>Buscar</b>: biblioteca o ayuntamiento<br><b>Contar</b>: con tus propias palabras"}, {"type": "quiz", "kicker": "Piensa como investigador", "h": "¿Dónde buscarías primero?", "q": "Si quieres conocer una leyenda de tu propio pueblo, ¿cuál es una buena fuente para empezar?", "opts": [{"t": "Preguntar a un abuelo o vecino mayor", "ok": true}, {"t": "Inventarla yo mismo sin investigar", "ok": false}, {"t": "Copiar una leyenda de otro país lejano", "ok": false}], "okMsg": "¡Muy bien! Las personas mayores suelen conocer historias transmitidas de generación en generación.", "noMsg": "Piénsalo de nuevo: lo mejor es preguntar a alguien de tu entorno, como un abuelo o vecino, que conozca las historias del lugar."}, {"type": "reflect", "kicker": "Comparte tu hallazgo", "h": "Cuenta la leyenda de tu tierra", "body": "Investiga una leyenda propia de tu ciudad, pueblo o provincia. Puede ser sobre un monumento, un río, una montaña o un personaje.", "prompt": "Escribe con tus propias palabras la leyenda local que encontraste, indicando de qué <b>lugar</b> es y qué la hace especial para tu comunidad."}]},
  "p3:Mar:4": {"title": "Contar de generación en generación", "steps": [{"type": "hook", "kicker": "Historias que no se olvidan", "h": "¿Por qué seguimos contando historias antiguas?", "scenario": "Las leyendas españolas han pasado de padres a hijos durante siglos, para que nadie olvide lo importante que aprendieron quienes vivieron antes que nosotros.", "body": "La Biblia también habla de contar historias importantes de generación en generación, pero no leyendas inventadas, sino las <b>obras verdaderas de Dios</b>."}, {"type": "theory", "kicker": "Un versículo para recordar", "h": "Salmo 78:4", "body": "El Salmo 78:4 dice: <b>«Contaremos a la generación venidera las alabanzas del Señor»</b>. Así como las leyendas se transmiten de abuelos a nietos, Dios pide a su pueblo que cuente a los niños y jóvenes todo lo bueno que Él ha hecho, para que su fe no se pierda con el tiempo.", "diagram": "<b>Leyendas</b>: se cuentan de generación en generación<br><b>Salmo 78:4</b>: contamos las alabanzas del Señor<br><b>Nuestra tarea</b>: no olvidar ni dejar de contar"}, {"type": "quiz", "kicker": "Comprende el versículo", "h": "¿Qué pide el Salmo 78:4?", "q": "Según el Salmo 78:4, ¿qué debemos hacer con las alabanzas del Señor?", "opts": [{"t": "Contarlas a la generación venidera", "ok": true}, {"t": "Guardarlas en secreto para nosotros solos", "ok": false}, {"t": "Olvidarlas con el paso del tiempo", "ok": false}], "okMsg": "¡Correcto! Dios nos pide compartir sus obras con los que vienen después de nosotros.", "noMsg": "Repasa el versículo: dice que debemos <b>contar</b> a la generación venidera las alabanzas del Señor, no callarlas ni olvidarlas."}, {"type": "reflect", "kicker": "Cierra tu cuaderno de leyendas", "h": "Tu propia \"alabanza\" para contar", "body": "Así como las leyendas se transmiten para no olvidarlas, piensa en algo bueno que Dios ha hecho en tu vida o en tu familia y que te gustaría contar a otros más pequeños.", "prompt": "Escribe una frase corta contando algo bueno que Dios ha hecho por ti o tu familia, como si se la fueras a contar a un niño más pequeño dentro de muchos años. Añádela como cierre de tu <b>Cuaderno de leyendas españolas</b>."}]},
  "p3:Abr:1": {"title": "770 años de camino", "steps": [{"type": "hook", "kicker": "Un viaje muy largo", "h": "¿Sabías que un proceso histórico puede durar casi 800 años?", "scenario": "En el año 722, un pequeño grupo de cristianos resistió en las montañas del norte de España. Casi 800 años después, en 1492, ese proceso terminaría por completo.", "body": "Ese largo camino se llama la <b>Reconquista</b>: el periodo en que los reinos cristianos fueron recuperando territorio, desde <b>Covadonga (722)</b> hasta <b>Granada (1492)</b>."}, {"type": "theory", "kicker": "De Covadonga a Granada", "h": "Cinco hitos de la Reconquista", "body": "La Reconquista no ocurrió en un solo día, sino a lo largo de <b>siglos</b>, con muchos avances y momentos importantes. Para entenderla bien, es útil ordenar sus hechos principales en una <b>línea de tiempo</b>, desde el inicio en Covadonga hasta el final en Granada.", "diagram": "<b>722</b>: Batalla de Covadonga (inicio)<br>…<br>Avances de los reinos cristianos<br>…<br><b>1492</b>: Toma de Granada (fin)"}, {"type": "quiz", "kicker": "Ubica los hechos", "h": "¿En qué años empieza y termina la Reconquista?", "q": "¿Qué años marcan el inicio y el final de la Reconquista?", "opts": [{"t": "722 (Covadonga) y 1492 (Granada)", "ok": true}, {"t": "1492 (Covadonga) y 722 (Granada)", "ok": false}, {"t": "1000 y 1500, aproximadamente", "ok": false}], "okMsg": "¡Exacto! La Reconquista comienza en Covadonga (722) y termina con la toma de Granada (1492).", "noMsg": "Revisa de nuevo: la Reconquista empieza en el año 722, en Covadonga, y finaliza en 1492, con la toma de Granada."}, {"type": "reflect", "kicker": "Construye tu línea de tiempo", "h": "Ordena la historia", "body": "Vas a crear tu propia línea de tiempo de la Reconquista, un proceso que duró casi 800 años.", "prompt": "Dibuja o escribe una línea de tiempo con <b>5 hitos principales</b> de la Reconquista entre el año 722 y el año 1492, indicando el año y qué ocurrió en cada uno."}]},
  "p3:Abr:2": {"title": "La reina que unió reinos", "steps": [{"type": "hook", "kicker": "Una mujer decisiva", "h": "¿Puede una sola persona cambiar el rumbo de un país?", "scenario": "En el siglo XV vivió una reina cuyas decisiones marcaron el final de la Reconquista y el comienzo de una nueva etapa para España.", "body": "Se trata de <b>Isabel I de Castilla</b>, quien junto a su esposo <b>Fernando de Aragón</b> formó a los llamados <b>Reyes Católicos</b>."}, {"type": "theory", "kicker": "Conoce a Isabel I", "h": "Fe, matrimonio y decisiones clave", "body": "Isabel I fue una reina de profunda <b>fe cristiana</b>, que gobernó junto a Fernando de Aragón. Su unión permitió unir dos grandes reinos. Entre sus decisiones más importantes están: <b>casarse con Fernando de Aragón</b> para unir Castilla y Aragón, <b>completar la Reconquista</b> tomando Granada en 1492, y <b>apoyar la expedición</b> que cambiaría la historia del mundo ese mismo año.", "diagram": "<b>Isabel I</b>: reina de Castilla, fe cristiana<br>Decisión 1: matrimonio con Fernando<br>Decisión 2: toma de Granada (1492)<br>Decisión 3: apoyo a nuevas expediciones"}, {"type": "quiz", "kicker": "Datos sobre Isabel I", "h": "¿Quién fue el esposo de Isabel I?", "q": "Isabel I de Castilla gobernó junto a su esposo, formando los Reyes Católicos. ¿Quién era él?", "opts": [{"t": "Fernando de Aragón", "ok": true}, {"t": "El Cid Campeador", "ok": false}, {"t": "Un rey de Granada", "ok": false}], "okMsg": "¡Correcto! Isabel de Castilla y Fernando de Aragón formaron juntos a los Reyes Católicos.", "noMsg": "No es correcto. El esposo de Isabel I fue Fernando de Aragón; juntos fueron los Reyes Católicos."}, {"type": "reflect", "kicker": "Crea su perfil", "h": "Ficha de Isabel I", "body": "Vas a elaborar una pequeña ficha con los datos más importantes de esta reina histórica.", "prompt": "Escribe un perfil breve de Isabel I con: su <b>fecha</b> como reina, un dato sobre su <b>fe cristiana</b>, y <b>3 decisiones importantes</b> que tomó."}]},
  "p3:Abr:3": {"title": "Un mapa que cambia", "steps": [{"type": "hook", "kicker": "España se transforma", "h": "¿Cómo cambió el mapa de España en 600 años?", "scenario": "Si compararas un mapa de la Península Ibérica del año 900 con uno de 1492, verías algo muy distinto: reinos que ya no existen y otros que crecieron mucho.", "body": "Esta semana compararás cómo se veía la <b>Península Ibérica</b> antes y después de la Reconquista, para entender mejor todo ese largo proceso."}, {"type": "theory", "kicker": "Dos mapas, dos épocas", "h": "La península en 900 y en 1492", "body": "En el año <b>900 d.C.</b>, gran parte de la Península estaba bajo el dominio de <b>Al-Ándalus</b>, mientras los reinos cristianos ocupaban solo el norte. En <b>1492</b>, tras siglos de Reconquista, los reinos cristianos ya controlaban casi todo el territorio, y ese año cayó <b>Granada</b>, el último reino musulmán en la península.", "diagram": "<b>900 d.C.</b>: Al-Ándalus grande + reinos cristianos pequeños en el norte<br><b>1492</b>: reinos cristianos unidos + caída de Granada"}, {"type": "quiz", "kicker": "Compara las épocas", "h": "¿Qué cambió entre el 900 y el 1492?", "q": "¿Qué diferencia principal hay entre el mapa de la Península en el año 900 y en el año 1492?", "opts": [{"t": "En 1492 los reinos cristianos controlaban casi todo el territorio", "ok": true}, {"t": "En 1492 Al-Ándalus ocupaba más territorio que en el 900", "ok": false}, {"t": "El mapa era exactamente igual en ambas fechas", "ok": false}], "okMsg": "¡Correcto! Con la Reconquista, los reinos cristianos fueron ganando territorio hasta 1492.", "noMsg": "Recuerda: entre el 900 y el 1492, los reinos cristianos crecieron mucho, mientras Al-Ándalus se redujo hasta la caída de Granada."}, {"type": "reflect", "kicker": "Dibuja el cambio", "h": "Compara los dos mapas", "body": "Vas a representar cómo cambió el territorio de la Península Ibérica antes y después de la Reconquista.", "prompt": "Dibuja dos mapas sencillos de la Península Ibérica, uno con el año <b>900 d.C.</b> y otro con el año <b>1492</b>, marcando qué zonas eran cristianas y cuáles no en cada época."}]},
  "p3:Abr:4": {"title": "El Juez más justo", "steps": [{"type": "hook", "kicker": "Mirar la historia con cuidado", "h": "¿Es fácil juzgar lo que pasó hace siglos?", "scenario": "La Reconquista tuvo momentos de fe, de valentía, pero también de guerra y sufrimiento para muchas personas. Juzgar hechos tan antiguos y complejos no es sencillo.", "body": "Cuando los humanos juzgamos, a veces nos equivocamos o somos injustos. Pero la Biblia nos habla de un <b>Juez que nunca se equivoca</b>."}, {"type": "theory", "kicker": "Un versículo para pensar", "h": "Salmo 9:8", "body": "El Salmo 9:8 dice: <b>«Él juzgará al mundo con justicia y a los pueblos con rectitud»</b>. A diferencia de los juicios humanos, que pueden equivocarse, <b>Dios juzga con perfecta justicia</b>, viendo toda la verdad de cada situación y de cada época de la historia.", "diagram": "<b>Juicios humanos</b>: pueden equivocarse<br><b>Salmo 9:8</b>: Dios juzga con justicia y rectitud<br><b>Aplicación</b>: mirar la historia con humildad"}, {"type": "quiz", "kicker": "Comprende el versículo", "h": "¿Cómo juzga Dios según el Salmo 9:8?", "q": "Según el Salmo 9:8, ¿cómo juzga Dios al mundo y a los pueblos?", "opts": [{"t": "Con justicia y rectitud", "ok": true}, {"t": "Sin fijarse en lo que realmente pasó", "ok": false}, {"t": "Favoreciendo siempre a un solo pueblo", "ok": false}], "okMsg": "¡Correcto! El Salmo 9:8 nos enseña que Dios juzga con justicia y rectitud, a diferencia de los juicios humanos.", "noMsg": "Repasa el versículo: dice que Dios juzga al mundo <b>con justicia</b> y a los pueblos <b>con rectitud</b>, no de forma parcial."}, {"type": "reflect", "kicker": "Cierra tu trabajo sobre la Reconquista", "h": "¿Cómo juzgamos la historia?", "body": "Piensa en todo lo aprendido sobre la Reconquista y los Reyes Católicos: hubo fe, valentía, pero también conflictos difíciles entre personas.", "prompt": "Escribe una breve reflexión respondiendo: <b>¿por qué es importante recordar que solo Dios juzga con perfecta justicia cuando miramos hechos históricos como la Reconquista?</b> Esta reflexión será parte de tu trabajo <b>«La Reconquista y los Reyes Católicos»</b>."}]},
  "p3:May:1": {"title": "¿Cuántos habitantes tiene España?", "steps": [{"type": "hook", "kicker": "Un país lleno de vida", "h": "¿Sabes cuántas personas viven contigo en España?", "scenario": "Imagina una fila gigante formada por todos los habitantes de España, uno detrás de otro. ¡No se acabaría nunca!", "body": "Este mes vamos a descubrir <b>cuánta gente vive en España</b> y, en concreto, en tu propia <b>comunidad autónoma</b>. Para eso necesitamos aprender a buscar datos reales, como hacen los geógrafos."}, {"type": "theory", "kicker": "Aprende a investigar", "h": "¿Qué es un habitante?", "body": "Un <b>habitante</b> es cada persona que vive en un lugar. Cuando sumamos a todos los habitantes de un país, obtenemos su <b>población total</b>. España está dividida en <b>comunidades autónomas</b> (como Andalucía, Cataluña o Madrid), y cada una tiene su propio número de habitantes. Para conocer estos datos, podemos consultar fuentes fiables como el <b>INE</b> (Instituto Nacional de Estadística) o mapas y libros de geografía.", "diagram": "<b>País</b> → España<br><b>Divisiones</b> → Comunidades autónomas<br><b>Dato que buscamos</b> → nº de habitantes de España y de tu comunidad"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Un momento para pensar", "q": "¿Qué palabra describe a cada persona que vive en un lugar?", "opts": [{"t": "Habitante", "ok": true}, {"t": "Turista", "ok": false}, {"t": "Comunidad", "ok": false}], "okMsg": "¡Exacto! Cada persona que vive en un lugar es un habitante.", "noMsg": "Casi... la palabra correcta es 'habitante'."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Investiga tu España", "body": "Busca en internet, en un libro o pregunta a un adulto para completar esta pequeña investigación.", "prompt": "Escribe el número de habitantes de España y el número de habitantes de tu comunidad autónoma. Si quieres, dibuja al lado un mapa sencillo señalando dónde vives."}]},
  "p3:May:2": {"title": "El mapa de la gente: ¿dónde vivimos más?", "steps": [{"type": "hook", "kicker": "Un mapa con secretos", "h": "¿Por qué hay pueblos casi vacíos y ciudades llenísimas?", "scenario": "Piensa en un pueblo pequeño del interior de España, con pocas calles y mucha tranquilidad. Ahora piensa en una ciudad costera llena de edificios y gente paseando por la playa.", "body": "Esta semana vamos a mirar un <b>mapa de densidad de población</b> de España para descubrir <b>dónde vive más gente y dónde vive menos</b>."}, {"type": "theory", "kicker": "Interior y costa", "h": "Densidad de población", "body": "La <b>densidad de población</b> nos dice cuánta gente vive en cada zona. En España, generalmente hay <b>más habitantes cerca de las costas</b> (por el clima, el turismo y el trabajo) y <b>menos habitantes en muchas zonas del interior</b>, donde hay grandes extensiones de campo con pocos pueblos. Un mapa de densidad usa colores: los tonos oscuros marcan zonas con mucha gente, y los tonos claros marcan zonas con poca gente.", "diagram": "<b>Costas</b> → normalmente más densidad de población<br><b>Interior</b> → normalmente menos densidad de población<br><b>Mapa de densidad</b> → colores oscuros = mucha gente, colores claros = poca gente"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Interior vs costa", "q": "En un mapa de densidad de población, ¿qué suele indicar una zona con color muy oscuro?", "opts": [{"t": "Una zona con muchos habitantes", "ok": true}, {"t": "Una zona sin ningún habitante", "ok": false}, {"t": "Una zona de montaña sin nombre", "ok": false}], "okMsg": "¡Correcto! Los colores oscuros suelen indicar zonas con mucha población.", "noMsg": "No exactamente. Los colores oscuros del mapa indican zonas con muchos habitantes."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Compara España", "body": "Busca o dibuja un mapa de densidad de población de España.", "prompt": "Anota 3 diferencias que observes entre las zonas del interior y las zonas de costa (por ejemplo: cantidad de gente, tipo de paisaje o actividades)."}]},
  "p3:May:3": {"title": "Las ciudades más grandes de España", "steps": [{"type": "hook", "kicker": "Gigantes de piedra y gente", "h": "¿Cuáles son las ciudades con más habitantes de España?", "scenario": "Si viajaras por España en tren, algunas paradas serían ciudades enormes, llenas de edificios altos, tiendas y millones de personas.", "body": "Esta semana investigamos <b>las 5 ciudades más grandes de España</b>: cómo se llaman, en qué comunidad autónoma están y cuántos habitantes tienen."}, {"type": "theory", "kicker": "Ciudades y comunidades", "h": "¿Cómo se organiza una ciudad grande?", "body": "Cada <b>ciudad</b> pertenece a una <b>comunidad autónoma</b>. Las ciudades más grandes suelen tener mucha actividad: trabajo, cultura, transporte y servicios, por eso atraen a tanta gente. Para investigar necesitamos tres datos de cada ciudad: su <b>nombre</b>, su <b>comunidad autónoma</b> y su <b>número de habitantes</b>.", "diagram": "<b>Ciudad</b> → nombre<br><b>Pertenece a</b> → una comunidad autónoma<br><b>Dato clave</b> → número de habitantes"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Datos de una ciudad", "q": "¿Qué tres datos necesitamos para investigar una ciudad grande?", "opts": [{"t": "Nombre, comunidad autónoma y habitantes", "ok": true}, {"t": "Nombre, color de la bandera y clima", "ok": false}, {"t": "Habitantes, animales y deportes", "ok": false}], "okMsg": "¡Muy bien! Esos son justo los tres datos que vamos a buscar.", "noMsg": "No es esa combinación. Los datos que buscamos son: nombre, comunidad autónoma y habitantes."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Tu lista de ciudades", "body": "Investiga en libros, internet o preguntando a un adulto.", "prompt": "Haz una lista de las 5 ciudades más grandes de España. Para cada una, escribe: su nombre, su comunidad autónoma y su número de habitantes."}]},
  "p3:May:4": {"title": "Fructificad y multiplicaos: la bendición de crecer", "steps": [{"type": "hook", "kicker": "Una bendición muy antigua", "h": "¿Sabías que Dios habló sobre las personas del mundo desde el principio?", "scenario": "Piensa en todos los millones de habitantes que hemos descubierto este mes en España. Cada una de esas personas forma parte de algo que empezó hace muchísimo tiempo.", "body": "Ya sabes cuántos habitantes tiene España, dónde viven y cuáles son sus ciudades más grandes. Ahora vamos a descubrir qué dice la Biblia sobre <b>llenar la tierra de personas</b>."}, {"type": "theory", "kicker": "La Palabra de Dios", "h": "Génesis 1:28", "body": "En <b>Génesis 1:28</b>, Dios bendice a las primeras personas y les dice: <i>'fructificad y multiplicaos y llenad la tierra'</i>. Esto significa que Dios quería que hubiera muchas personas viviendo en el mundo, cuidándolo y llenándolo de vida. Cada habitante de España, de tu comunidad autónoma y de las grandes ciudades que investigaste forma parte de esa bendición que empezó hace muchísimo tiempo.", "diagram": "<b>Génesis 1:28</b> → 'fructificad y multiplicaos, y llenad la tierra'<br><b>Significado</b> → Dios bendice el crecimiento de las personas<br><b>Hoy</b> → España está llena de habitantes, parte de esa bendición"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "El versículo de mayo", "q": "Según Génesis 1:28, ¿qué les pidió Dios a las primeras personas?", "opts": [{"t": "Que fructificaran, se multiplicaran y llenaran la tierra", "ok": true}, {"t": "Que construyeran ciudades muy altas", "ok": false}, {"t": "Que contaran cuántas comunidades autónomas había", "ok": false}], "okMsg": "¡Así es! Dios los bendijo para que llenaran la tierra de vida.", "noMsg": "No es esa la respuesta. Dios les pidió que fructificaran, se multiplicaran y llenaran la tierra."}, {"type": "reflect", "kicker": "Tu entregable final", "h": "Infografía de la población española", "body": "Ha llegado el momento de reunir todo lo que investigaste este mes.", "prompt": "Crea una <b>infografía de la población española</b>: incluye los habitantes de España y tu comunidad autónoma, las 3 diferencias entre interior y costa, la lista de las 5 ciudades más grandes, y una frase que recuerde Génesis 1:28."}]},
  "p3:Jun:1": {"title": "Las primeras palabras en castellano", "steps": [{"type": "hook", "kicker": "Un tesoro escondido en un monasterio", "h": "¿Cómo eran las primerísimas palabras escritas en castellano?", "scenario": "Imagina a un monje, hace más de mil años, escribiendo pequeñas notas al margen de un libro en latín para entender mejor lo que leía.", "body": "Esas notas se llaman <b>Glosas Emilianenses</b> y contienen algunas de las primeras palabras escritas en <b>castellano</b> que se conocen. Esta semana las vamos a leer."}, {"type": "theory", "kicker": "Un documento muy especial", "h": "¿Qué son las Glosas Emilianenses?", "body": "Las <b>Glosas Emilianenses</b> son pequeñas anotaciones escritas por un monje en los márgenes de un libro en latín, para explicar su significado. Están consideradas uno de los primeros testimonios escritos del <b>castellano</b>. Aunque el idioma de esa época suena distinto al de hoy, si lees la <b>transcripción moderna</b> podrás reconocer algunas palabras parecidas a las que usamos ahora.", "diagram": "<b>Glosas Emilianenses</b> → notas al margen de un libro en latín<br><b>Escritas en</b> → castellano muy antiguo<br><b>Importancia</b> → primeras palabras conocidas en castellano"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué son las Glosas?", "q": "¿Qué son las Glosas Emilianenses?", "opts": [{"t": "Anotaciones antiguas con algunas de las primeras palabras en castellano", "ok": true}, {"t": "Un mapa de las ciudades de España", "ok": false}, {"t": "Una canción religiosa moderna", "ok": false}], "okMsg": "¡Correcto! Son anotaciones muy antiguas con palabras tempranas del castellano.", "noMsg": "No es correcto. Las Glosas Emilianenses son anotaciones con algunas de las primeras palabras en castellano."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Lee y reconoce", "body": "Busca la transcripción moderna de las Glosas Emilianenses (puedes pedir ayuda a un adulto o a tu profesor).", "prompt": "Lee la transcripción moderna de las Glosas Emilianenses y escribe al menos 3 palabras que reconozcas porque se parecen a palabras que usamos hoy."}]},
  "p3:Jun:2": {"title": "Del latín al castellano de hoy", "steps": [{"type": "hook", "kicker": "Un viaje de mil años", "h": "¿Cómo cambian las palabras con el paso del tiempo?", "scenario": "Piensa en un juego del teléfono roto que dura siglos: una palabra en latín va cambiando poco a poco, de boca en boca, hasta convertirse en la palabra que usas hoy.", "body": "Esta semana vamos a construir una <b>tabla de evolución</b> que muestre cómo las palabras pasaron del <b>latín</b> al <b>castellano medieval</b> y de ahí al <b>castellano actual</b>."}, {"type": "theory", "kicker": "Tres etapas de una palabra", "h": "Latín, castellano medieval y castellano actual", "body": "Nuestro idioma no apareció de golpe: es el resultado de una <b>evolución</b>. Primero se hablaba <b>latín</b>. Con el tiempo, el latín cambió y se transformó en el <b>castellano medieval</b>, que ya se parecía más al español de hoy pero sonaba distinto. Finalmente, ese castellano medieval siguió evolucionando hasta convertirse en el <b>castellano actual</b> que hablamos tú y yo.", "diagram": "<b>Latín</b> → lengua antigua de origen<br><b>Castellano medieval</b> → etapa intermedia<br><b>Castellano actual</b> → la lengua que hablamos hoy"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "El camino de las palabras", "q": "¿Cuál es el orden correcto de la evolución de nuestra lengua?", "opts": [{"t": "Latín → castellano medieval → castellano actual", "ok": true}, {"t": "Castellano actual → latín → castellano medieval", "ok": false}, {"t": "Castellano medieval → castellano actual → latín", "ok": false}], "okMsg": "¡Exacto! Ese es el camino que siguió nuestra lengua.", "noMsg": "No es ese el orden. El camino correcto es: latín → castellano medieval → castellano actual."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Tu tabla de evolución", "body": "Investiga o pregunta a un adulto sobre el origen de algunas palabras que usamos cada día.", "prompt": "Elabora una tabla con 5 palabras, mostrando su forma en latín, en castellano medieval y en castellano actual."}]},
  "p3:Jun:3": {"title": "Palabras que vienen de muy lejos", "steps": [{"type": "hook", "kicker": "Palabras viajeras", "h": "¿Sabías que usas palabras que tienen cientos de años?", "scenario": "Cada vez que hablas, usas palabras que nacieron hace muchísimo tiempo y que viajaron de generación en generación hasta llegar a ti.", "body": "Después de conocer las Glosas Emilianenses y la tabla de evolución del idioma, esta semana vas a <b>usar tú mismo</b> palabras de origen medieval en un texto propio."}, {"type": "theory", "kicker": "Escribir con historia", "h": "Palabras que sobrevivieron al tiempo", "body": "Muchas palabras que usamos hoy en día ya existían, con formas parecidas, en el <b>castellano medieval</b>. Cuando las usamos en una frase, estamos conectando con personas que vivieron hace siglos. Escribir un párrafo con palabras de origen medieval es como tender un puente entre el pasado y el presente.", "diagram": "<b>Palabra medieval</b> → sigue viva hoy<br><b>Tú la usas</b> → en frases de todos los días<br><b>Resultado</b> → un puente entre pasado y presente"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Palabras con historia", "q": "¿Por qué decimos que algunas palabras de hoy 'tienen historia'?", "opts": [{"t": "Porque ya existían, con formas parecidas, en el castellano medieval", "ok": true}, {"t": "Porque las inventamos ayer", "ok": false}, {"t": "Porque solo se usan en otros países", "ok": false}], "okMsg": "¡Muy bien! Esas palabras vienen de mucho tiempo atrás.", "noMsg": "No es correcto. Tienen historia porque ya existían, con formas parecidas, en el castellano medieval."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu párrafo", "body": "Usa la tabla de evolución que hiciste la semana pasada como ayuda.", "prompt": "Escribe un párrafo (4-6 frases) usando al menos 5 palabras de origen medieval que sigues usando hoy."}]},
  "p3:Jun:4": {"title": "Una lengua pura: el don de hablar bien", "steps": [{"type": "hook", "kicker": "Un regalo para cuidar", "h": "¿Sabías que la Biblia habla también de las palabras y las lenguas?", "scenario": "Después de investigar las Glosas Emilianenses y ver cómo evolucionó nuestro idioma, es momento de mirar el lenguaje desde otra perspectiva: como un regalo de Dios.", "body": "El profeta <b>Sofonías</b> escribió algo hermoso sobre las palabras y los pueblos. Esta semana descubrimos qué significa."}, {"type": "theory", "kicker": "La Palabra de Dios", "h": "Sofonías 3:9", "body": "En <b>Sofonías 3:9</b> Dios promete: <i>'Entonces devolveré a los pueblos una lengua pura'</i>. Una <b>lengua pura</b> es un idioma usado para decir la verdad, bendecir y comunicarse con respeto y amor. El castellano que hoy hablamos, con toda su historia desde el latín hasta las Glosas Emilianenses, es un <b>don</b> (un regalo) que también es una <b>responsabilidad</b>: usarlo bien, para el bien de los demás.", "diagram": "<b>Sofonías 3:9</b> → 'daré a los pueblos palabra pura'<br><b>Lengua pura</b> → hablar con verdad y respeto<br><b>Nuestra lengua</b> → un don y una responsabilidad"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "El versículo de junio", "q": "Según Sofonías 3:9, ¿qué promete Dios a los pueblos?", "opts": [{"t": "Devolverles una lengua pura", "ok": true}, {"t": "Enseñarles a escribir en latín", "ok": false}, {"t": "Construirles ciudades nuevas", "ok": false}], "okMsg": "¡Correcto! Dios promete devolver a los pueblos una lengua pura.", "noMsg": "No es esa la respuesta. Sofonías 3:9 dice que Dios devolverá a los pueblos una lengua pura."}, {"type": "reflect", "kicker": "Tu entregable final", "h": "El origen de nuestras palabras", "body": "Reúne todo lo investigado este mes: las Glosas Emilianenses, la tabla de evolución y tu párrafo con palabras medievales.", "prompt": "Prepara tu trabajo 'El origen de nuestras palabras': incluye 2 o 3 palabras de las Glosas, tu tabla de 5 palabras (latín-medieval-actual), tu párrafo con palabras medievales, y una frase que explique qué significa para ti que el castellano sea 'un don y una responsabilidad'."}]},
  "p3:Jul:1": {"title": "Detectives de la Historia: mi comunidad autónoma", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 1", "h": "¿Sabías que tu propia tierra guarda secretos increíbles?", "scenario": "Ana va a visitar a su abuela y le pregunta: '¿Qué cosas importantes han pasado aquí, en nuestra tierra?' Su abuela sonríe y dice: 'Prepárate, porque hay mucho que contar.'", "body": "Este mes vas a convertirte en un <b>detective de la historia</b>. Tu misión: descubrir <b>3 eventos históricos importantes</b> de tu comunidad autónoma, ese trocito de España donde vives. ¡Todo lo que aprendiste este curso te va a ayudar!"}, {"type": "theory", "kicker": "Cómo investigar como un experto", "h": "Un evento histórico deja huellas", "body": "Un <b>evento histórico</b> es algo importante que ocurrió en el pasado y que cambió la vida de las personas: una batalla, la llegada de un rey, la construcción de un monumento, un descubrimiento. Para investigar puedes preguntar a tus abuelos o familiares, buscar en libros, o pensar en los <b>castillos, iglesias o monumentos</b> de tu región: ¡cada uno cuenta una historia!", "diagram": "MI INVESTIGACIÓN<br><b>Evento 1:</b> ¿Qué pasó? ¿Cuándo?<br><b>Evento 2:</b> ¿Qué pasó? ¿Cuándo?<br><b>Evento 3:</b> ¿Qué pasó? ¿Cuándo?<br>Fuente: familia, libros, monumentos"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "¿Qué es un evento histórico?", "q": "¿Cuál de estas opciones es un ejemplo de evento histórico de una región?", "opts": [{"t": "La construcción de un castillo medieval hace muchos años", "ok": true}, {"t": "Lo que desayunaste esta mañana", "ok": false}, {"t": "El color de tu mochila", "ok": false}], "okMsg": "¡Correcto! Un castillo medieval es una huella del pasado que nos cuenta una historia real.", "noMsg": "Casi. Piensa en algo que ocurrió hace mucho tiempo y que cambió la vida de la gente de tu región."}, {"type": "reflect", "kicker": "Mi tarea de investigación", "h": "Empieza tu dossier", "body": "Recuerda todo lo que aprendiste este curso sobre visigodos, reinos medievales, la Reconquista y los Reyes Católicos: seguro que alguna de esas piezas de la historia pasó también en tu propia comunidad autónoma.", "prompt": "Investiga y escribe 3 eventos históricos importantes de tu comunidad autónoma. Para cada uno anota: qué pasó, cuándo ocurrió aproximadamente, y por qué fue importante. Pregunta a tu familia o busca en un libro."}]},
  "p3:Jul:2": {"title": "Dibujo mi región: historia y geografía juntas", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 2", "h": "¿Podrías dibujar tu región con los ojos cerrados?", "scenario": "Con los 3 eventos históricos ya investigados, Ana coge un lápiz y un papel grande. 'Ahora voy a dibujar dónde pasó todo esto', piensa mientras mira un mapa de España.", "body": "Esta semana vas a crear algo muy especial: un <b>mapa comentado</b> de tu región, donde la <b>historia</b> y la <b>geografía</b> se encuentran. ¡Como un tesoro dibujado a mano!"}, {"type": "theory", "kicker": "Un mapa que cuenta historias", "h": "Historia + Geografía + Personajes", "body": "Un <b>mapa comentado</b> no es solo un dibujo: tiene <b>notas y dibujos</b> que explican cosas. Debe mostrar la <b>geografía</b> de tu región (montañas, ríos, costa o llanuras), el lugar donde ocurrieron tus 3 eventos históricos, y algún <b>personaje importante</b> relacionado con tu tierra (un rey, una reina, un santo o una persona famosa).", "diagram": "MI MAPA COMENTADO<br><b>Geografía:</b> montañas, ríos, costa...<br><b>Historia:</b> marca dónde ocurrieron tus 3 eventos<br><b>Personajes:</b> dibuja o nombra a alguien importante"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "¿Qué debe llevar tu mapa?", "q": "¿Qué elemento NO debería faltar en tu mapa comentado?", "opts": [{"t": "El lugar donde ocurrieron tus eventos históricos", "ok": true}, {"t": "Un dibujo de tu plato de comida favorito", "ok": false}, {"t": "El nombre de un cantante extranjero", "ok": false}], "okMsg": "¡Exacto! El mapa debe mostrar dónde pasó tu historia, junto con la geografía y los personajes.", "noMsg": "Recuerda: el mapa une geografía, historia y personajes de tu propia región."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Crea tu mapa", "body": "Usa una hoja grande o una cartulina. Puedes pintar montañas, ríos o costa, y marcar con un símbolo especial (una estrella, una bandera) los lugares de tus eventos históricos.", "prompt": "Dibuja el mapa de tu comunidad autónoma. Señala su geografía principal, marca los lugares de tus 3 eventos históricos y añade al menos 1 personaje importante relacionado con tu región."}]},
  "p3:Jul:3": {"title": "Mi región en palabras: el texto expositivo", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 3", "h": "¿Y si tuvieras que explicarle tu región a alguien que nunca ha estado allí?", "scenario": "Ana ya tiene su mapa terminado. Ahora quiere escribir todo lo que sabe, para que hasta un niño de otro país pudiera entender cómo es su tierra.", "body": "Esta semana vas a escribir un <b>texto expositivo</b>, igual que aprendiste a hacer este curso: un texto claro que <b>explica</b> ideas con orden, usando datos reales sobre tu comunidad autónoma."}, {"type": "theory", "kicker": "Recordando el texto expositivo", "h": "Explicar con orden: inicio, desarrollo y cierre", "body": "Un <b>texto expositivo</b> explica un tema con <b>claridad y orden</b>. Tu texto de <b>15 oraciones</b> puede organizarse así: unas oraciones para presentar tu región, otras para contar tus 3 eventos históricos, otras para hablar de la geografía, y una frase final para cerrar con orgullo.", "diagram": "MI TEXTO EXPOSITIVO (15 oraciones)<br><b>Inicio:</b> presento mi comunidad autónoma<br><b>Desarrollo:</b> mis 3 eventos históricos + geografía<br><b>Cierre:</b> una frase que resuma por qué es especial"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "¿Cómo es un buen texto expositivo?", "q": "¿Qué característica debe tener tu texto expositivo?", "opts": [{"t": "Explicar ideas reales con orden y claridad", "ok": true}, {"t": "Estar lleno de rimas inventadas sin sentido", "ok": false}, {"t": "No tener ni inicio ni final", "ok": false}], "okMsg": "¡Muy bien! Un texto expositivo explica con orden y claridad, usando datos verdaderos.", "noMsg": "Piensa de nuevo: un texto expositivo debe explicar algo real, con un orden claro."}, {"type": "reflect", "kicker": "A escribir", "h": "Redacta tu texto", "body": "Usa tu investigación de la semana 1 y tu mapa de la semana 2 como ayuda. Escribe con letra clara y revisa que cada oración tenga sentido.", "prompt": "Escribe un texto expositivo de 15 oraciones sobre tu comunidad autónoma: presenta tu región, cuenta tus 3 eventos históricos, describe su geografía y termina con una frase de cierre."}]},
  "p3:Jul:4": {"title": "¡Mi región en la historia! Presentación y fin de curso", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 4 · Gran cierre", "h": "¡Ha llegado el gran día!", "scenario": "Ana coloca su mapa en la pared, sujeta su texto en las manos y respira hondo. Toda la clase la mira. 'Voy a contarles la historia de mi tierra', piensa con una sonrisa.", "body": "Esta semana presentas tu <b>dossier completo</b>: investigación, mapa y texto. Y también celebramos algo enorme: <b>todo un curso</b> de historia, geografía y lengua que has aprendido paso a paso."}, {"type": "theory", "kicker": "Presentar con seguridad", "h": "5 minutos para brillar", "body": "Para tu <b>presentación oral de 5 minutos</b> titulada 'Mi región en la historia', habla <b>despacio y claro</b>, muestra tu mapa mientras explicas, y cuenta tus 3 eventos con orgullo. Mirar a quien te escucha y sonreír te ayudará a sentirte más seguro.", "diagram": "MI PRESENTACIÓN (5 min)<br><b>1.</b> Presento mi región<br><b>2.</b> Muestro mi mapa y explico<br><b>3.</b> Cuento mis 3 eventos históricos<br><b>4.</b> Cierro con una frase memorable"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "¿Cómo hacer una buena presentación oral?", "q": "¿Qué es lo más importante al presentar tu dossier ante la clase?", "opts": [{"t": "Hablar claro, mostrar el mapa y contar los eventos con seguridad", "ok": true}, {"t": "Leer muy rápido sin mirar a nadie", "ok": false}, {"t": "Esconder el mapa detrás de la espalda", "ok": false}], "okMsg": "¡Perfecto! Hablar con claridad y mostrar tu trabajo con seguridad es la clave de una gran presentación.", "noMsg": "Recuerda: habla despacio, muestra tu mapa y cuenta tus eventos con orgullo."}, {"type": "reflect", "kicker": "Cierre del curso · Deuteronomio 4:9", "h": "Guarda tu alma para no olvidar", "body": "La Biblia nos dice: <i>'Guarda tu alma para que no olvides las cosas que tus ojos han visto'</i> (Deuteronomio 4:9). Este curso tus ojos han visto muchas cosas: los visigodos, los climas de España, los reinos medievales y el Camino de Santiago, las leyendas españolas, la Reconquista y los Reyes Católicos, cómo se formó la población de España y el origen del castellano. Todo eso ahora es parte de tu memoria y de tu historia.", "prompt": "Practica tu presentación oral de 5 minutos: 'Mi región en la historia'. Preséntala a tu familia o a tu clase. Después, escribe en una frase qué es lo que más te ha gustado aprender este curso, y da gracias a Dios por todo lo aprendido."}]},
});
